<?php
session_start(); require_once __DIR__.'/../fastfood/database.php'; require_once __DIR__.'/../fastfood/lang.php';
$id=(int)($_GET['order_id']??0); $ids=array_map('intval',$_SESSION['my_orders']??[]);
if(!$id || !in_array($id,$ids,true)){http_response_code(403);die('Buyurtma topilmadi.');}
$st=$pdo->prepare("SELECT o.*,c.name courier_name,c.phone courier_phone,c.vehicle,c.current_lat,c.current_lng,c.location_updated_at FROM orders o LEFT JOIN delivery_couriers c ON c.id=o.courier_id WHERE o.id=? AND o.order_type='delivery'");$st->execute([$id]);$o=$st->fetch();if(!$o){http_response_code(404);die('Buyurtma topilmadi.');}
$labels=['new'=>'Yangi','assigned'=>'Kuryer biriktirildi','picked_up'=>'Buyurtma olindi','on_the_way'=>'Yo‘lda','delivered'=>'Yetkazildi','cancelled'=>'Bekor qilindi'];
$label=$labels[$o['delivery_status']??'new']??($o['status']??'');
?>
<!doctype html><html lang="<?=htmlspecialchars(ff_current_lang())?>"><head><meta charset="utf-8"><link rel="icon" type="image/svg+xml" href="../img/favicon.svg"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Buyurtma #<?=$id?> — Kuzatish</title><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/theme-elegant.css?v=1"><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><script src="../js/theme.js"></script><style>
.track-wrap{max-width:1100px;margin:0 auto;padding:34px 18px 70px}.track-head{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:20px}.track-head h1{margin:4px 0}.track-card{background:var(--card,#fff);border:1px solid rgba(0,0,0,.08);border-radius:24px;padding:20px;box-shadow:0 14px 35px rgba(0,0,0,.06)}.track-grid{display:grid;grid-template-columns:1.3fr .7fr;gap:20px}.map{height:500px;border-radius:18px;overflow:hidden;background:#eef2f3}.status-main{font-size:28px;font-weight:900;margin:4px 0 18px}.status-pill{display:inline-block;padding:8px 12px;border-radius:999px;background:#fff3cd;font-weight:800}.courier-box{margin-top:16px;padding:16px;border-radius:18px;background:rgba(217,54,54,.06)}.dot{width:10px;height:10px;border-radius:50%;background:#1aa260;display:inline-block;margin-right:6px}.muted{color:var(--muted,#777)}.steps{display:grid;gap:10px;margin-top:18px}.step{display:flex;gap:10px;align-items:center;padding:11px 12px;border-radius:13px;background:rgba(0,0,0,.035)}.step.active{background:rgba(217,54,54,.1);font-weight:800}@media(max-width:800px){.track-grid{grid-template-columns:1fr}.map{height:380px}}
