<main class="track-wrap"><div class="track-head"><div><span class="food-kicker">LIVE DELIVERY</span><h1>Buyurtma #<?=$id?></h1><p class="muted">Kuryer qayerda ekanini kuzating.</p></div><a class="btn btn-secondary" href="../fastfood/my_orders.php">← Buyurtmalarim</a></div><div class="track-grid"><section class="track-card"><div id="map" class="map"></div><div id="mapNote" class="muted" style="margin-top:10px">Kuryer lokatsiyasi kutilyapti…</div></section><aside class="track-card"><div class="muted">Hozirgi holat</div><div id="status" class="status-main"><?=htmlspecialchars($label)?></div><span id="pill" class="status-pill"><?=htmlspecialchars($label)?></span><div class="steps"><div data-st="new" class="step">🆕 Yangi</div><div data-st="assigned" class="step">👨‍✈️ Kuryer biriktirildi</div><div data-st="picked_up" class="step">📦 Buyurtma olindi</div><div data-st="on_the_way" class="step">🛵 Yo‘lda</div><div data-st="delivered" class="step">✅ Yetkazildi</div></div><div id="courierBox" class="courier-box"><b>Kuryer ma'lumoti</b><p id="courierInfo" class="muted">Kuryer hali biriktirilmagan.</p></div><p class="muted" id="updated" style="margin-top:14px"></p></aside></div></main>
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>
const orderId=<?=$id?>; const dest=[<?=json_encode((float)$o['delivery_lat'])?>,<?=json_encode((float)$o['delivery_lng'])?>];
const map=L.map('map').setView(dest[0]&&dest[1]?dest: [41.3111,69.2797],15);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);
let destMarker=null,courierMarker=null,first=true;if(dest[0]&&dest[1]) destMarker=L.marker(dest).addTo(map).bindPopup('📍 Yetkazish manzili');
const labels={new:'Yangi',assigned:'Kuryer biriktirildi',picked_up:'Buyurtma olindi',on_the_way:'Yo‘lda',delivered:'Yetkazildi',cancelled:'Bekor qilindi'};
function refresh(){fetch('track_api.php?order_id='+orderId,{cache:'no-store'}).then(r=>r.json()).then(d=>{if(!d.ok)return;const o=d.order,st=o.delivery_status||'new';document.getElementById('status').textContent=labels[st]||st;document.getElementById('pill').textContent=labels[st]||st;document.querySelectorAll('.step').forEach(x=>x.classList.toggle('active',x.dataset.st===st));if(o.courier_name){document.getElementById('courierInfo').innerHTML='<span class="dot"></span>'+o.courier_name+(o.vehicle?' · '+o.vehicle:'')+(o.courier_phone?'<br>📞 '+o.courier_phone:'');}else document.getElementById('courierInfo').textContent='Kuryer hali biriktirilmagan.';if(o.current_lat&&o.current_lng){const pos=[+o.current_lat,+o.current_lng];if(!courierMarker)courierMarker=L.marker(pos).addTo(map).bindPopup('🛵 Kuryer');else courierMarker.setLatLng(pos);if(first){map.setView(pos,15);first=false;}document.getElementById('mapNote').textContent='🟢 Kuryer lokatsiyasi yangilanmoqda';document.getElementById('updated').textContent=o.location_updated_at?'Oxirgi yangilanish: '+o.location_updated_at:'';}else document.getElementById('mapNote').textContent='Kuryer lokatsiyasi hali mavjud emas.';}).catch(()=>{});}refresh();setInterval(refresh,10000);
</script><script src="../js/lang-switch.js"></script><script src="../js/global-i18n.js"></script><script src="../js/lang-switch.js"></script><script src="../js/universal-i18n.js"></script></body></html>
